1	// See-it-fail fixture for tldr/comment-class-menu: a line carrying anything
2	// beyond the class it names must produce exactly one finding, and every
3	// conforming shape must produce none.
4	//
5	// The fixture drives the rule through the engine's own dispatch seam (runRule +
6	// buildContext with a transcript path), not by hand-rolling a work object — so
7	// the test proves the rule as the Stop hook actually runs it.
8	//
9	// Run it directly (no npm script owns .claudinite/local/packs):
10	//   node --test .claudinite/local/packs/tldr/comment-class-menu.test.mjs
11	
12	import { test } from 'node:test';
13	import assert from 'node:assert/strict';
14	import { mkdtempSync, writeFileSync } from 'node:fs';
15	import { tmpdir } from 'node:os';
16	import { join, resolve, dirname } from 'node:path';
17	import { fileURLToPath } from 'node:url';
18	
19	import rule from './comment-class-menu.mjs';
20	import { buildContext } from '../../../shared/engine/checks/helpers/repo-context.mjs';
21	import { runRule } from '../../../shared/engine/checks/helpers/work.mjs';
22	
23	const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
24	const scratch = mkdtempSync(join(tmpdir(), 'tldr-comment-class-'));
25	
26	// A minimal Claude Code transcript: one owner turn, then the assistant reply
27	// whose classification line is under test. These are the shapes
28	// session-transcript.mjs reads (a plain-string user message, an assistant
29	// content array of text blocks).
30	function transcriptWith(replyText) {
31	  const entries = [
32	    { type: 'user', timestamp: '2026-07-31T00:00:00Z', message: { role: 'user', content: 'please look at the release job' } },
33	    { type: 'assistant', timestamp: '2026-07-31T00:00:01Z', message: { role: 'assistant', content: [{ type: 'text', text: replyText }] } },
34	  ];
35	  const path = join(scratch, `t-${Math.random().toString(36).slice(2)}.jsonl`);
36	  writeFileSync(path, `${entries.map((e) => JSON.stringify(e)).join('\n')}\n`);
37	  return path;
38	}
39	
40	const findingsFor = (replyText) =>
41	  runRule(rule, buildContext({ root: repoRoot, mode: 'changed', transcriptPath: transcriptWith(replyText) }));
42	
43	test('fires on the menu-restating line that poisoned the 2026-07-26 sessions', () => {
44	  const found = findingsFor('Comment class: other — not a correction, feature request, or process-change\n\nOn it.');
45	  assert.equal(found.length, 1);
46	  assert.equal(found[0].rule, 'tldr/comment-class-menu');
47	  assert.equal(found[0].severity, 'advisory');
48	  // Every class the classifier actually reads off the line is named back.
49	  for (const declared of ['correction', 'feature', 'process-change', 'other']) {
50	    assert.match(found[0].what, new RegExp(declared), `finding should name the declared class ${declared}`);
51	  }
52	});
53	
54	// The three cases below are why this rule checks the form instead of hunting a
55	// negation word: each declares a class in plain prose, negating nothing, and an
56	// intent-inferring draft of this rule stayed silent on all three.
57	
58	test('fires on a stray class smuggled in without negating anything', () => {
59	  const found = findingsFor('Comment class: other — unrelated to any feature request\n\nProceeding.');
60	  assert.equal(found.length, 1);
61	  assert.match(found[0].what, /feature/);
62	  // `feature` is the one that arms a BLOCKING rule, so the finding says so.
63	  assert.match(found[0].what, /feature-requirements-first/);
64	});
65	
66	test('fires on a class named while being set aside', () => {
67	  const found = findingsFor('Comment class: other, setting the feature question to one side');
68	  assert.equal(found.length, 1);
69	  assert.match(found[0].what, /feature/);
70	});
71	
72	test('fires on the menu pasted verbatim out of the prompt', () => {
73	  const found = findingsFor('Comment class: correction | feature | process-change | other');
74	  assert.equal(found.length, 1);
75	  // `|` is the menu's separator, never a declaration separator.
76	  assert.match(found[0].what, /correction/);
77	  assert.match(found[0].what, /feature/);
78	});
79	
80	test('fires on an explanation sharing the line even when it smuggles no class', () => {
81	  const found = findingsFor('Comment class: correction — fixed the typo');
82	  assert.equal(found.length, 1);
83	  assert.match(found[0].what, /correction/);
84	  // Nothing armed a blocking rule here, so the finding does not claim otherwise.
85	  assert.doesNotMatch(found[0].what, /feature-requirements-first/);
86	});
87	
88	test('silent on the class declared alone', () => {
89	  assert.deepEqual(findingsFor('Comment class: other\n\nNot a correction, feature request, or process-change — just a note.'), []);
90	});
91	
92	test('silent on an honest multi-class declaration', () => {
93	  assert.deepEqual(findingsFor('Comment class: correction, process-change\n\nFixing it and updating the procedure.'), []);
94	});
95	
96	test('silent on a multi-class declaration joined by "and"', () => {
97	  assert.deepEqual(findingsFor('Comment class: correction and process-change'), []);
98	});
99	
100	test('silent on a trailing period', () => {
101	  assert.deepEqual(findingsFor('Comment class: other.'), []);
102	});
103	
104	test('silent when there is no classification line at all (comment-classification owns that)', () => {
105	  assert.deepEqual(findingsFor('Sure, doing that now.'), []);
106	});
107	
108	test('silent when the line names no known class at all (comment-classification owns that)', () => {
109	  assert.deepEqual(findingsFor('Comment class: misc'), []);
110	});
111

1	// Session-transcript parsing for conversation-surface rules (Stop hook only —
2	// CI has no transcript, so rules must return [] when ctx.conversation() is null).
3	// A Claude Code transcript is JSONL; the shapes this reads were verified against
4	// a real session file, not inferred: an owner turn is `type: "user"` with plain
5	// string message content (tool results arrive as content arrays, injected/meta
6	// turns carry isMeta, subagent traffic carries isSidechain, and synthetic turns
7	// — hook output, reminders, webhook activity — are tag-wrapped, starting with "<").
8	
9	export function parseEntries(text) {
10	  const entries = [];
11	  for (const line of (text || '').split('\n')) {
12	    if (!line.trim()) continue;
13	    try { entries.push(JSON.parse(line)); } catch { /* partial trailing write — skip the line */ }
14	  }
15	  return entries;
16	}
17	
18	function humanText(entry) {
19	  if (entry.type !== 'user' || entry.isMeta || entry.isSidechain) return null;
20	  const content = entry.message?.content;
21	  const text = typeof content === 'string'
22	    ? content
23	    : Array.isArray(content) && content.length && content.every((c) => c?.type === 'text')
24	      ? content.map((c) => c.text).join('\n')
25	      : null;
26	  if (!text || text.trimStart().startsWith('<')) return null;
27	  return text;
28	}
29	
30	// The owner's own turns, in order: [{ index, timestamp, text }].
31	export function humanTurns(entries) {
32	  const turns = [];
33	  entries.forEach((entry, index) => {
34	    const text = humanText(entry);
35	    if (text !== null) turns.push({ index, timestamp: entry.timestamp ?? null, text });
36	  });
37	  return turns;
38	}
39	
40	// Concatenated assistant text emitted after entry `fromIndex`, up to the next
41	// owner turn (or the end of the session).
42	export function assistantTextAfter(entries, fromIndex) {
43	  const parts = [];
44	  for (let i = fromIndex + 1; i < entries.length; i += 1) {
45	    const entry = entries[i];
46	    if (humanText(entry) !== null) break;
47	    if (entry.type !== 'assistant') continue;
48	    const content = entry.message?.content;
49	    if (!Array.isArray(content)) continue;
50	    for (const block of content) {
51	      if (block?.type === 'text' && block.text) parts.push(block.text);
52	    }
53	  }
54	  return parts.join('\n');
55	}
56	
57	// The explicit classification line, if the reply carries one.
58	export function classificationLine(text) {
59	  const m = /^[ \t>#*_-]*comment\s+class\b[^:\n]*:(.*)$/im.exec(text || '');
60	  return m ? m[0] : null;
61	}
62	
63	// Canonical class tokens named on a classification line (a mixed comment may
64	// name several): 'correction' | 'feature' | 'process-change' | 'other'.
65	export function classesIn(line) {
66	  const classes = new Set();
67	  for (const m of (line || '').matchAll(/correction|feature|process[\s-]change|other/gi)) {
68	    classes.add(m[0].toLowerCase().replace(/\s+/g, '-'));
69	  }
70	  return classes;
71	}
72	
73	// Each owner turn with the classes its reply declared (empty set = unclassified).
74	export function classifiedTurns(entries) {
75	  return humanTurns(entries).map((turn) => ({
76	    ...turn,
77	    classes: classesIn(classificationLine(assistantTextAfter(entries, turn.index))),
78	  }));
79	}
80

1	import { dirname, join, normalize } from 'node:path';
2	import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
3	import { addedLines } from './line-scanning.mjs';
4	import { extractLinks } from './markdown.mjs';
5	
6	// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
7	// transcript, no merge-base, an empty branch all yield empty results — so a rule
8	// reads as one chain with no guard ladders. Mechanism only: a rule still owns
9	// its patterns, file filters, and failure text.
10	//
11	// A rule declaring `scope: 'work'` receives this object as its `run` argument
12	// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
13	// world object exists. The raw surface a work rule still needs (files, read,
14	// exists, …) is delegated here, so a work rule — and the structural helpers it
15	// calls, e.g. findExtensionManifest — never touches ctx itself.
16	export const work = (ctx) => new Work(ctx);
17	
18	// The single dispatch seam: the runner and every rule test invoke rules through
19	// this, so a rule's scope decides its context in exactly one place. Extra args
20	// pass through (some rules take test-only options after the context).
21	export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);
22	
23	// Null-object for "no such turn": every accessor answers emptily, so a chain
24	// ending in .last() never needs an existence guard before its predicates.
25	const NO_TURN = {
26	  exists: false, text: '', timestamp: null,
27	  excerpt: () => '', reply: () => '', classified: () => false,
28	  classes: () => new Set(), time: () => 0,
29	};
30	
31	class Turn {
32	  constructor(entries, { index, timestamp, text }) {
33	    this.entries = entries;
34	    this.index = index;
35	    this.timestamp = timestamp;
36	    this.text = text;
37	    this.exists = true;
38	  }
39	
40	  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
41	  reply() { return assistantTextAfter(this.entries, this.index); }
42	  classified() { return classificationLine(this.reply()) !== null; }
43	  classes() { return classesIn(classificationLine(this.reply())); }
44	  time() { return Date.parse(this.timestamp ?? '') || 0; }
45	}
46	
47	// Array subclass so filter/map stay chainable and .last() survives them.
48	class Turns extends Array {
49	  last() { return this.length ? this[this.length - 1] : NO_TURN; }
50	}
51	
52	class Conversation {
53	  constructor(entries) { this.entries = entries ?? []; }
54	
55	  ownerTurns() {
56	    const turns = new Turns();
57	    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
58	    return turns;
59	  }
60	}
61	
62	class Work {
63	  constructor(ctx) { this.ctx = ctx; }
64	
65	  get branch() { return this.ctx.branch; }
66	  get baseRef() { return this.ctx.baseRef; }
67	  get commits() { return this.ctx.commits; }
68	  get files() { return this.ctx.files; }
69	  get changedFiles() { return this.ctx.changedFiles; }
70	  get tracked() { return this.ctx.tracked; }
71	  // The discovered pack objects (runner-attached) and the normalized config —
72	  // the pair a rule that reasons over pack metadata (e.g. adoption-interview
73	  // state) hands to the interview helpers, without reaching into ctx itself.
74	  get packs() { return this.ctx.packs ?? []; }
75	  get config() { return this.ctx.config; }
76	  read(path) { return this.ctx.read(path); }
77	  readBase(path) { return this.ctx.readBase(path); }
78	  exists(path) { return this.ctx.exists(path); }
79	  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }
80	
81	  conversation() { return new Conversation(this.ctx.conversation()); }
82	
83	  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }
84	
85	  onDefaultBranch() { return this.ctx.branch === 'main' || this.ctx.branch === 'master'; }
86	
87	  introducedMerges() { return this.ctx.introducedMergeCommits(); }
88	
89	  // Branch commits since the merge-base, oldest first, each with a parsed .time.
90	  branchCommits() {
91	    return this.ctx.commitsWithFiles().map((c) => ({ ...c, time: Date.parse(c.date) || 0 }));
92	  }
93	
94	  // `file` parsed as JSON at head and at the scoping base; a side that is
95	  // absent or unparsable is null, so set-vs-base rules need no try/catch.
96	  jsonPair(file) {
97	    const parse = (text) => {
98	      if (text === null) return null;
99	      try { return JSON.parse(text); } catch { return null; }
100	    };
101	    return { head: parse(this.ctx.read(file)), base: parse(this.ctx.readBase(file)) };
102	  }
103	
104	  filesContaining(needle, files = this.ctx.files) {
105	    return files.filter((f) => (this.ctx.read(f) ?? '').includes(needle));
106	  }
107	
108	  // Relative Markdown links that resolve to nothing: [{ file, line, target, resolved }].
109	  // Links reaching outside the repo aren't verifiable here and are skipped.
110	  deadLinks(files) {
111	    const out = [];
112	    for (const file of (files ?? this.ctx.files).filter((f) => f.endsWith('.md'))) {
113	      const text = this.ctx.read(file);
114	      if (text === null) continue;
115	      for (const { target, line } of extractLinks(text)) {
116	        const resolved = normalize(join(dirname(file), target));
117	        if (resolved.startsWith('..') || this.ctx.exists(resolved)) continue;
118	        out.push({ file, line, target, resolved });
119	      }
120	    }
121	    return out;
122	  }
123	
124	  // Tracked lines still naming a path this change deletes: [{ file, line, text, gone }].
125	  // A hit whose every occurrence widens to a path token that still resolves is a
126	  // rename that kept the basename, not a dangling reference — dropped. `tolerated(gone)`
127	  // lets the rule exempt paths something else deliberately governs.
128	  danglingReferences(tolerated = () => false) {
129	    const out = [];
130	    for (const gone of this.ctx.deleted) {
131	      if (tolerated(gone)) continue;
132	      for (const hit of this.ctx.grepTracked(gone)) {
133	        if (hit.file === gone || referencesSurvivingPath(hit, gone, this.ctx)) continue;
134	        out.push({ ...hit, gone });
135	      }
136	    }
137	    return out;
138	  }
139	}
140	
141	const PATH_CHAR = /[\w./@-]/;
142	
143	function widenToken(text, start, end) {
144	  let s = start;
145	  let e = end;
146	  while (s > 0 && PATH_CHAR.test(text[s - 1])) s--;
147	  while (e < text.length && PATH_CHAR.test(text[e])) e++;
148	  return text.slice(s, e);
149	}
150	
151	function referencesSurvivingPath(hit, gone, ctx) {
152	  let idx = hit.text.indexOf(gone);
153	  if (idx === -1) return false;
154	  while (idx !== -1) {
155	    const token = widenToken(hit.text, idx, idx + gone.length);
156	    const resolved = normalize(join(dirname(hit.file), token));
157	    if (!((token !== gone && ctx.exists(token)) || ctx.exists(resolved))) return false;
158	    idx = hit.text.indexOf(gone, idx + 1);
159	  }
160	  return true;
161	}
162

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { findExtensionManifest } from '../../engine/checks/helpers/chrome-manifest.mjs';
3	
4	const rule = {
5	  id: 'cer/version-sync',
6	  severity: 'blocking',
7	  description: "The manifest's version is the single source of truth; package.json must equal it",
8	  doc: 'packs/chrome-extension-release/RELEASE.md',
9	  why: 'a version that diverges ships the wrong number to the store or refuses to publish',
10	
11	  run(ctx) {
12	    const manifestPath = findExtensionManifest(ctx);
13	    if (!manifestPath) return [];
14	    let manifest;
15	    try { manifest = JSON.parse(ctx.read(manifestPath)); } catch { return []; }
16	    const pkgText = ctx.read('package.json');
17	    if (pkgText === null) {
18	      return [finding(rule, {
19	        file: 'package.json',
20	        what: 'missing — the release pipeline builds via npm run build at the repo root',
21	        fix: 'add the root package.json with version equal to the manifest\'s',
22	      })];
23	    }
24	    let pkg;
25	    try { pkg = JSON.parse(pkgText); } catch { return []; }
26	    if (manifest.version !== pkg.version) {
27	      return [finding(rule, {
28	        file: manifestPath,
29	        what: `manifest version ${manifest.version} != package.json version ${pkg.version}`,
30	        fix: 'bump both together — "bump version" edits the manifest and package.json in the same change',
31	      })];
32	    }
33	    return [];
34	  },
35	};
36	
37	export default rule;
38

